    private static let toEnglish = translations.map { ($0.key, $0.value) }.sorted { ($0.0.count, $0.0) > ($1.0.count, $1.0) }
    private static let toSpanish = translations.map { ($0.value, $0.key) }.sorted { ($0.0.count, $0.0) > ($1.0.count, $1.0) }

    static func display(_ text: String, language: String) -> String {
        let pairs = language == "en" ? toEnglish : toSpanish
        let source = language == "en" ? text.replacingOccurrences(of: "Respuesta simulada inválida: ", with: "") : text
        return pairs.reduce(source) { $0.replacingOccurrences(of: $1.0, with: $1.1) }
    }

    static func message(_ message: NotebookMessage, language: String) -> String {
        // Old fallback replies predate the explicit app-generated marker.
        let legacyStatus = message.role == "assistant" && message.appGenerated == nil &&
            (message.text == "Sin cambios." || message.text == "No changes." ||
             message.text.range(of: #"^(Cambios guardados · [0-9]+ archivo\(s\)\.|Changes saved · [0-9]+ file\(s\)\.)$"#, options: .regularExpression) != nil)
        return message.role == "error" || message.appGenerated == true || legacyStatus
            ? display(message.text, language: language) : message.text
    }
}
